ALTER TABLE posts ADD COLUMN comment_count INT NOT NULL DEFAULT 0;

CREATE FUNCTION bump_comment_count() RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE posts SET comment_count = comment_count + 1 WHERE id = NEW.post_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE posts SET comment_count = comment_count - 1 WHERE id = OLD.post_id;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER comments_count_trigger
AFTER INSERT OR DELETE ON comments
FOR EACH ROW EXECUTE FUNCTION bump_comment_count();

-- Reads are now trivially cheap: no join, no COUNT(*)
SELECT id, title, comment_count FROM posts ORDER BY created_at DESC LIMIT 20;

CREATE TABLE products (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    price NUMERIC(10, 2) NOT NULL,
    attributes JSONB NOT NULL DEFAULT '{}'
);

CREATE INDEX idx_products_attributes ON products USING GIN (attributes);

INSERT INTO products (name, category, price, attributes) VALUES
    ('Blue T-Shirt', 'apparel', 19.99, '{"size": "M", "color": "blue"}'),
    ('ThinkBook 14', 'laptop', 899.00, '{"ram_gb": 16, "screen_inches": 14}');

SELECT name FROM products WHERE attributes @> '{"color": "blue"}';
SELECT name, price FROM products WHERE category = 'laptop' AND (attributes->>'ram_gb')::int >= 16;

-- EAV anti-pattern: no types, no constraints, painful multi-attribute filtering
CREATE TABLE entity_attributes (
    entity_id BIGINT NOT NULL,
    attribute_name TEXT NOT NULL,
    attribute_value TEXT NOT NULL
);

-- Finding laptops with >= 16GB RAM requires a self-join per attribute filtered on
SELECT e1.entity_id
FROM entity_attributes e1
JOIN entity_attributes e2 ON e2.entity_id = e1.entity_id
WHERE e1.attribute_name = 'type' AND e1.attribute_value = 'laptop'
  AND e2.attribute_name = 'ram_gb' AND e2.attribute_value::int >= 16;

-- Fix: table-per-type, with real typed columns and constraints
CREATE TABLE products (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE laptops (
    product_id BIGINT PRIMARY KEY REFERENCES products(id),
    ram_gb INT NOT NULL CHECK (ram_gb > 0),
    screen_inches NUMERIC(4,1) NOT NULL
);

SELECT p.name, l.ram_gb
FROM products p JOIN laptops l ON l.product_id = p.id
WHERE l.ram_gb >= 16;

