-- migration: 20260201090000_add_discount_code_to_orders

-- up
ALTER TABLE orders ADD COLUMN discount_code TEXT;

-- down
ALTER TABLE orders DROP COLUMN discount_code;

-- Blocks writes to orders for the ENTIRE index build on a large table:
CREATE INDEX idx_orders_customer_id ON orders (customer_id);

-- Builds the same index without holding that write-blocking lock:
CREATE INDEX CONCURRENTLY idx_orders_customer_id ON orders (customer_id);

-- Adding a CHECK constraint: NOT VALID takes only a brief lock;
-- new writes are checked immediately; existing rows are verified
-- later, without blocking concurrent reads/writes during validation.
ALTER TABLE orders ADD CONSTRAINT positive_amount CHECK (amount > 0) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT positive_amount;

