-- on every insert/update; still read from `email`.

-- Step 3 (backfill): copy existing values into the new column
UPDATE users SET email_address = email WHERE email_address IS NULL;

-- Step 4 (app deploy only): read from `email_address` instead of `email`;
-- keep writing both for safety during this transition.

-- Step 5 (migration + deploy, once nothing reads/writes `email` anymore):
ALTER TABLE users DROP COLUMN email;

sections.body:
A foreign key's `ON DELETE` clause specifies exactly what Postgres should do to a child row when the parent row it references is deleted. There are four standard behaviors.

```sql
CREATE TABLE posts (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    author_id BIGINT NOT NULL REFERENCES authors(id) ON DELETE RESTRICT,
    title TEXT NOT NULL
);

CREATE TABLE post_tags (
    post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    tag_id  BIGINT NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,
    PRIMARY KEY (post_id, tag_id)
);

CREATE TABLE comments (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
    body TEXT NOT NULL
);
```

**RESTRICT** refuses the DELETE on the parent outright, with an error, if any child row still references it -- you must explicitly delete or reassign the child rows first. Postgres's actual default, when no `ON DELETE` clause is specified at all, is **NO ACTION**, which is subtly different from RESTRICT only in one respect: RESTRICT's check cannot be deferred to the end of a transaction even if the constraint is declared `DEFERRABLE`, while NO ACTION's check can be, if explicitly set up that way -- for the overwhelming majority of schemas that don't use deferrable constraints, RESTRICT and the NO ACTION default behave identically, blocking the delete with a foreign key violation error. **CASCADE** automatically deletes every child row referencing the deleted parent, propagating the delete downward. **SET NULL** leaves the child row in place but sets its foreign key column to NULL, severing the link while keeping the row itself -- this only works if the foreign key column is nullable. A fourth, less common option, **SET DEFAULT**, sets the foreign key column to whatever default value was declared for it (rather than NULL) when the parent is deleted.

**Soft deletion** sidesteps the entire CASCADE/RESTRICT/SET NULL decision for a given table by never actually issuing a hard `DELETE` against it at all: instead, a `deleted_at TIMESTAMPTZ` column (NULL for active rows, set to the deletion time for 'deleted' ones) marks a row as logically gone, while it continues to physically exist in the table.

```sql
ALTER TABLE users ADD COLUMN deleted_at TIMESTAMPTZ;

-- "Deleting" a user:
UPDATE users SET deleted_at = now() WHERE id = 42;

-- Every query that should only see active users needs this filter:
SELECT * FROM users WHERE deleted_at IS NULL;

-- A unique constraint needs to apply only to non-deleted rows,
-- otherwise a re-registration with the same email is blocked forever:
CREATE UNIQUE INDEX idx_users_email_active ON users (email) WHERE deleted_at IS NULL;
```

Since the `users` row never actually disappears, every foreign key referencing it automatically stays valid with zero CASCADE/RESTRICT/SET NULL decision required at the database level -- a comment's `user_id` simply continues pointing at a row that still exists, just one that's now flagged as deleted. This solves the immediate orphaning problem neatly, but introduces its own, different costs: every single query against `users` (and, transitively, often against anything joined to it) now has to remember to filter out soft-deleted rows, which is easy to forget in a new query and turns into a correctness bug the moment it is; a plain `UNIQUE` constraint on `email` would incorrectly block a legitimate new signup reusing an email a deleted account once held, requiring a partial unique index scoped to `deleted_at IS NULL` instead, as shown above; and 'deleting' something no longer actually frees any storage or genuinely removes the data (a real concern for legal or privacy requirements to actually erase specific data on request, which soft deletion alone does not satisfy). Soft deletion is a legitimate, common pattern -- particularly good fit for user-facing 'undo my delete' features -- but it is a trade-off, not a strictly superior alternative to choosing a deliberate ON DELETE strategy; many real systems use both, hard-deleting some tables with carefully chosen FK strategies while soft-deleting others where recoverability matters more.

examples.code:
CREATE TABLE authors (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE users   (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name TEXT NOT NULL);

CREATE TABLE posts (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    author_id BIGINT NOT NULL REFERENCES authors(id) ON DELETE RESTRICT,
    title TEXT NOT NULL
);

CREATE TABLE comments (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
    body TEXT NOT NULL
);

-- Author still has a post -- RESTRICT blocks this delete
DELETE FROM authors WHERE id = 1;
-- ERROR:  update or delete on table "authors" violates foreign key constraint

-- Deleting a post CASCADEs to its comments -- they're gone too
DELETE FROM posts WHERE id = 5;
-- comments where post_id = 5 are deleted automatically

-- Deleting a user SET NULLs their comments' user_id -- the comments remain
DELETE FROM users WHERE id = 7;
-- comments where user_id = 7 now have user_id = NULL, body unchanged

-- If ALL of these used ON DELETE CASCADE (not the mixed strategy above):
CREATE TABLE posts (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    author_id BIGINT NOT NULL REFERENCES authors(id) ON DELETE CASCADE,  -- risky
    title TEXT NOT NULL
);

CREATE TABLE comments (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    body TEXT NOT NULL
);

CREATE TABLE post_tags (
    post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    tag_id  BIGINT NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,
    PRIMARY KEY (post_id, tag_id)
);

-- One statement, unbounded downstream damage:
DELETE FROM authors WHERE id = 1;
-- silently also deletes: every post by author 1, every comment on
-- every one of those posts (regardless of WHO wrote the comment),
-- and every post_tags row for every one of those posts

CREATE TABLE users (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email TEXT NOT NULL,
    deleted_at TIMESTAMPTZ
);

-- Unique only among ACTIVE (non-deleted) users
CREATE UNIQUE INDEX idx_users_email_active ON users (email) WHERE deleted_at IS NULL;

INSERT INTO users (email) VALUES ('amy@example.com');

UPDATE users SET deleted_at = now() WHERE email = 'amy@example.com';

-- Succeeds: the old row is soft-deleted, so this doesn't collide with it
INSERT INTO users (email) VALUES ('amy@example.com');

-- Every ordinary query must remember to exclude soft-deleted rows:
SELECT * FROM users WHERE email = 'amy@example.com' AND deleted_at IS NULL;

